  name: "Default",
  render: () => <div className="shell">
      {/* Sidebar — Chat List with conversations */}
      <div className="shell__sidebar">
        <Header title="Chats" actions={[{
        icon: "more_vert",
        onClick: () => {},
        ariaLabel: "More"
      }]} />
        <SearchBar placeholder="Search" />
        <div style={{
        flex: 1,
        overflow: "auto"
      }}>
          {avatars.slice(0, 8).map((a, i) => <ConversationItem key={i} title={a.name} avatarUrl={a.imageUrl} textContent="Hey, how are you doing?" timestamp="4:56 pm" avatarVariant="image" />)}
        </div>
        {/* Tab bar */}
        <div className="shell__tab-bar">
          <TabItem icon="chat" label="Chats" active />
          <TabItem icon="call" label="Calls" />
          <TabItem icon="group" label="Groups" />
          <TabItem icon="person" label="Users" />
        </div>
      </div>

      {/* Main — Empty state */}
      <div className="shell__main">
        <div className="shell__empty">
          <div className="shell__empty-icon">
            <span className="icon-rounded" style={{
            fontSize: 48,
            color: "var(--cometchat-icon-color-tertiary)"
          }}>chat</span>
          </div>
          <div>
            <p className="shell__empty-title"><T>Welcome to Your Conversations</T></p>
            <p className="shell__empty-description"><T>Select a chat from the list to start exploring your messages or begin a new conversation</T></p>
          </div>
        </div>
      </div>
    </div>
